"""
rhino_modules_to_blender.py
===========================
Auto-generated from a Rhino model:  163 objects / 14 block definitions ("modules").

Each Rhino BLOCK DEFINITION is rebuilt here as a Blender mesh, then the whole
building is re-assembled using the ORIGINAL instance transforms extracted from
Rhino.  The Rhino block/instance hierarchy is preserved:

    MASTER  "1111"          -> 61 instances (the whole building)
        |__ VERTICALFRAME   -> is itself a sub-assembly of 6 instances
                (CON-UPPER x2, CON-LOWER x2, "1" x2)

Geometry is SHARED (linked-duplicate) so instances of the same module point at
one mesh datablock -- exactly like Rhino blocks.  VERTICALFRAME is built as a
nested Blender COLLECTION and placed with collection-instance empties.

HOW TO RUN
----------
Blender > Scripting workspace > paste > Run Script
   ...or from a shell:   blender --python rhino_modules_to_blender.py

Coordinates are kept 1:1 with Rhino.  Set UNIT_SCALE below to e.g. 0.01 to
shrink the model 100x if the Rhino file was in mm and you want a smaller scene.
"""

import bpy
import mathutils

UNIT_SCALE = 1.0            # global scale applied to the whole assembly
ROOT_COLLECTION = "RhinoModel"

# =====================================================================
#  PARSERS  (mesh data is stored verbatim as "x,y,z;..." / "a,b,c;...")
# =====================================================================

def parse_verts(s):
    out = []
    for c in s.strip().strip(";").split(";"):
        if not c:
            continue
        x, y, z = c.split(",")
        out.append((float(x), float(y), float(z)))
    return out

def parse_faces(s):
    out = []
    for c in s.strip().strip(";").split(";"):
        if not c:
            continue
        a, b, cc = c.split(",")
        out.append((int(a), int(b), int(cc)))
    return out

def parse_boxes(s):
    """min/max box list -> combined (verts, faces)."""
    verts, faces = [], []
    for c in s.strip().strip(";").split(";"):
        if not c:
            continue
        x0, y0, z0, x1, y1, z1 = map(float, c.split(","))
        b = len(verts)
        verts += [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0),
                  (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)]
        for f in [(0, 1, 2, 3), (4, 5, 6, 7), (0, 1, 5, 4),
                  (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)]:
            faces.append(tuple(b + i for i in f))
    return verts, faces

def matrix_from_row(line):
    """'Name|m00,m01,m02,m03,m10,...,m23' -> (name, mathutils.Matrix 4x4)."""
    name, nums = line.split("|")
    m = [float(v) for v in nums.split(",")]
    mat = mathutils.Matrix((
        (m[0], m[1], m[2], m[3]),
        (m[4], m[5], m[6], m[7]),
        (m[8], m[9], m[10], m[11]),
        (0.0, 0.0, 0.0, 1.0)))
    return name, mat

def parse_assembly(raw):
    return [matrix_from_row(l) for l in raw.strip().splitlines() if l.strip()]

# =====================================================================
#  BUILDERS
# =====================================================================

_mesh_cache = {}

def build_module_mesh(name):
    """Create (once) and return the mesh datablock for a leaf module."""
    if name in _mesh_cache:
        return _mesh_cache[name]
    if name == "FRAME-HORIZONTAL":
        verts, faces = parse_boxes(FRAME_H_BOXES)       # proxy: 34 members
    else:
        v, f = MESH[name]
        verts, faces = parse_verts(v), parse_faces(f)
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, [], faces)
    me.validate()
    me.update()
    _mesh_cache[name] = me
    return me

def get_collection(name, parent):
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
        parent.children.link(col)
    return col

def add_instance(module_name, matrix, into_collection, scale_mat):
    """Linked-duplicate: new object sharing the module's mesh datablock."""
    me = build_module_mesh(module_name)
    obj = bpy.data.objects.new(module_name, me)
    obj.matrix_world = scale_mat @ matrix
    into_collection.objects.link(obj)
    return obj

# =====================================================================
#  VERTICALFRAME  (nested sub-assembly -> its own collection)
# =====================================================================

def build_verticalframe_collection(root):
    col = bpy.data.collections.new("VERTICALFRAME_def")
    # NOT linked to the scene root -> used only as an instance source
    for name, mat in parse_assembly(VERTICALFRAME_RAW):
        me = build_module_mesh(name)
        o = bpy.data.objects.new(name, me)
        o.matrix_world = mat            # local to the VERTICALFRAME block
        col.objects.link(o)
    return col

def place_collection_instance(col, matrix, into, scale_mat):
    empty = bpy.data.objects.new("VERTICALFRAME", None)
    empty.instance_type = 'COLLECTION'
    empty.instance_collection = col
    empty.matrix_world = scale_mat @ matrix
    into.objects.link(empty)
    return empty

# =====================================================================
#  MAIN
# =====================================================================

def build_all():
    scene_root = bpy.context.scene.collection
    root = get_collection(ROOT_COLLECTION, scene_root)
    scale_mat = mathutils.Matrix.Scale(UNIT_SCALE, 4)

    vframe_col = build_verticalframe_collection(root)

    # per-module collections so the outliner groups instances by module
    counts = {}
    for name, mat in parse_assembly(MASTER_RAW):
        counts[name] = counts.get(name, 0) + 1
        if name == "VERTICALFRAME":
            place_collection_instance(vframe_col, mat, root, scale_mat)
        else:
            col = get_collection("mod_" + name, root)
            add_instance(name, mat, col, scale_mat)

    print("\n=== ASSEMBLY COMPLETE ===")
    for k in sorted(counts):
        print(f"  {k:16s} x{counts[k]}")
    print(f"  total top-level instances: {sum(counts.values())}")


